/* adcionado 16/10 */
/* variaveis que gerenciam as cores */
:root{
    --cor-contraste: #00BFFF;
    --segunda-cor-contraste: #000000;
    --terceira-cor-contraste: white;
  }

/* metodos principasi do contraste */
  .contraste , .contraste p, .contraste b, .contraste h1 , .contraste h2, .contraste h3, .contraste h3, .contraste h4, .contraste li, .contraste ul{
    background-color: var(--segunda-cor-contraste) !important;
    color: var(--cor-contraste) !important; 
  }
/* metodos para os botoes */
  .contraste button {
    border: 1px solid var(--terceira-cor-contraste) !important;
    color: var(--cor-contraste) !important;
  }

/* borda para menus especificos */
  .contraste.category, .contraste.card, .contraste.btn-block{
    border: 1px solid var(--terceira-cor-contraste) !important;
  }

  /* metodo pra cor de cinza no fundo*/
  .contraste.hero-wrapper{
    background-color:var(--terceira-cor-contraste) !important;
    background-blend-mode: luminosity !important;
  }

  /* metodo de contraste nos links */
  .contraste a, .contraste input, .contraste i{
    color: var(--cor-contraste) !important;
  }

  .contraste.card .contraste.arquivos-download a{
    background-color: var(--segunda-cor-contraste) !important;
  }


  /* metodo para cores cinzas nas imagens */
  /* .contraste img{ 
  filter: grayscale(1);
  }
  .contraste .blocks__item.has-image {
  background-blend-mode: difference !important;
  }  
  */


#rodape {
  background-color: #2C354A;
  border-top: 1px solid #262e40;
  height: auto;
  margin: 0;
  margin-bottom: -20px;
  padding: 40px;
  width: 100%
}

#rodape .info {
  display: -webkit-box;
  display: -webkit-flex;
  display: -ms-flexbox;
  display: flex;
  -webkit-flex-wrap: wrap;
  -ms-flex-wrap: wrap;
  flex-wrap: wrap;
  -webkit-box-pack: justify;
  -webkit-justify-content: space-between;
  -ms-flex-pack: justify;
  justify-content: space-between;
  padding: 0;
}

#rodape .info .info-column {
  -webkit-box-flex: 1;
  -webkit-flex: auto;
  -ms-flex: auto;
  flex: auto;
  -webkit-flex-basis: calc(100% / 3);
  -ms-flex-preferred-size: calc(100% / 3);
  flex-basis: calc(100% / 3);
}

@media (max-width: 480px) {
  #rodape .info .info-column {
    -webkit-flex-basis: 100%;
    -ms-flex-preferred-size: 100%;
    flex-basis: 100%;
  }
}

#rodape .info .info-column hr {
  border-color: #278AAE;
}

#rodape .info .info-column .info-block {
  margin: 50px 0;
}

#rodape .info .info-column .info-block:first-child {
  margin-top: 0;
}

#rodape .info .info-column .info-block h4 {
  margin-bottom: 15px;
}

#rodape .info .info-column .info-block li {
  float: none;
  margin: 15px 0;
  padding: 0;
}

#rodape .info .info-column .info-block a {
  color: #FFFFFF !important;
  font-size: 16px;
  font-weight: 300;
}

#rodape .info .info-column .info-block i {
  color: #278AAE;
  font-size: 28px;
  margin-right: 15px;
}

