.btn-primary {
  background-color: #FD9812;
  transition: background-color .4s;
  -webkit-transition: background-color .4s;
}

.btn-primary:hover {
  background-color: #fdae45;
  transition: background-color .4s;
  -webkit-transition: background-color .4s;
}

