.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.sr-only-focusable:active, .sr-only-focusable:focus {
  position: static;
  width: auto;
  height: auto;
  margin: 0;
  overflow: visible;
  clip: auto;
}

html, body {
  font-family: 'Montserrat', sans-serif !important;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a:visited {
  color: inherit;
}

.orange {
  color: #FD9812 !important;
}

.mini-header {
  background: #2C354A;
  display: -webkit-box;
  display: -webkit-flex;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-align: center;
  -webkit-align-items: center;
  -ms-flex-align: center;
  align-items: center;
  -webkit-box-pack: justify;
  -webkit-justify-content: space-between;
  -ms-flex-pack: justify;
  justify-content: space-between;
  padding: 0 30px;
  height: 50px;
}

@media (max-width: 991px) {
  .mini-header {
    display: none;
  }
}

.mini-header ul {
  display: -webkit-box;
  display: -webkit-flex;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-align: center;
  -webkit-align-items: center;
  -ms-flex-align: center;
  align-items: center;
  list-style: none;
  padding: 0;
  margin: 0;
}

.mini-header ul li {
  color: #09A3D3;
  font-size: 1rem;
  
}

.mini-header ul li a {
  -webkit-transition: all .1s ease-in-out;
  transition: all .1s ease-in-out;
  text-align: center;
}

.mini-header ul li a:hover {
  text-decoration: none;
}

.mini-header__items li {
  margin-right: 30px;
  text-align: center;
}

@media (max-width: 1171px) {
  .mini-header__items li {
    margin-right: 10px;
  }
}


.mini-header__items a {
  color: #FFFFFF;
}

.mini-header__items a:hover {
  color: #09A3D3;
}

.mini-header__social li {
  margin-left: 15px;
}

.mini-header__social li, .mini-header__social a {
  color: #09A3D3;
}

.mini-header__social i {
  font-size: 1.8rem;
}

.header {
  position: relative;
  display: -webkit-box;
  display: -webkit-flex;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-align: center;
  -webkit-align-items: center;
  -ms-flex-align: center;
  align-items: center;
  padding: 0 30px;
  height: 120px;
  background: #FFFFFF;
  border-bottom: 1px solid #E7E7E7;
}

@media (max-width: 767px) {
  .header {
    padding: 0 20px;
    height: 60px;
  }
}

.header a {
  -webkit-transition: all .2s ease-in-out;
  transition: all .2s ease-in-out;
}

.header__brand {
  -webkit-flex-basis: 225px;
  -ms-flex-preferred-size: 225px;
  flex-basis: 225px;
  -webkit-flex-shrink: 0;
  -ms-flex-negative: 0;
  flex-shrink: 0;
}

@media (max-width: 1199px) {
  .header__brand {
    -webkit-flex-basis: 190px;
    -ms-flex-preferred-size: 190px;
    flex-basis: 190px;
  }
